package mailbox

import (
	"bytes"
	"encoding/hex"
	"encoding/json"
	"os"
	"path/filepath"
	"testing"
)

// The vectors are generated by docs/protocol/v2/vectors/gen. The module copy in internal/v2/testdata
// keeps the package tests standalone; TestVectorCopyMatchesSpec keeps it in sync with the spec.
const (
	vectorCopy = "../testdata/kdf.json"
	vectorSpec = "../../../../docs/protocol/v2/vectors/kdf.json"
)

func TestVectorCopyMatchesSpec(t *testing.T) {
	a, err := os.ReadFile(vectorSpec)
	if err != nil {
		if os.IsNotExist(err) {
			t.Skip("spec vectors are not shipped in this checkout")
		}
		t.Fatal(err)
	}
	b, err := os.ReadFile(vectorCopy)
	if err != nil {
		t.Fatal(err)
	}
	norm := func(p []byte) []byte { return bytes.ReplaceAll(p, []byte("\r\n"), []byte("\n")) }
	if !bytes.Equal(norm(a), norm(b)) {
		t.Fatal("internal/v2/testdata/kdf.json differs from docs/protocol/v2/vectors/kdf.json")
	}
}

func kdfAll(t testing.TB) map[string]any {
	t.Helper()
	b, err := os.ReadFile(vectorCopy)
	if err != nil {
		t.Fatalf("read vectors: %v", err)
	}
	var all map[string]any
	if err := json.Unmarshal(b, &all); err != nil {
		t.Fatalf("parse vectors: %v", err)
	}
	return all
}

func kdfVector(t testing.TB) map[string]any {
	t.Helper()
	m, ok := kdfAll(t)["mailbox2"].(map[string]any)
	if !ok {
		t.Fatal("kdf.json has no mailbox2 section")
	}
	return m
}

func vhex(t testing.TB, m map[string]any, key string) []byte {
	t.Helper()
	s, ok := m[key].(string)
	if !ok {
		t.Fatalf("vector %q is missing", key)
	}
	b, err := hex.DecodeString(s)
	if err != nil {
		t.Fatalf("vector %q: %v", key, err)
	}
	return b
}

func TestVectorDepositFrame(t *testing.T) {
	v := kdfVector(t)
	raw := vhex(t, v, "deposit")
	d, err := ParseDeposit(raw)
	if err != nil {
		t.Fatalf("parse vector deposit: %v", err)
	}
	if d.Req != 9 {
		t.Fatalf("req %d, want 9", d.Req)
	}
	if !bytes.Equal(d.Queue, bytes.Repeat([]byte{0x90}, QueueSize)) {
		t.Fatalf("queue %x", d.Queue)
	}
	seal := kdfAll(t)["chat2_seal"].(map[string]any)
	if want := vhex(t, seal, "SealedEnvelope"); !bytes.Equal(d.Blob, want) {
		t.Fatalf("blob %x is not chat2_seal.SealedEnvelope", d.Blob)
	}
	if !bytes.Equal(d.Append(nil), raw) {
		t.Fatalf("the vector deposit does not re-encode to itself")
	}
}

func TestVectorForwardKey(t *testing.T) {
	v := kdfVector(t)
	ephSK := vhex(t, v, "forward_eph_sk")
	ephPub := vhex(t, v, "forward_eph_pub")
	hsM := vhex(t, v, "hs_M")
	wantK := vhex(t, v, "k")

	k, err := forwardKey(ephSK, hsM)
	if err != nil {
		t.Fatalf("forwardKey: %v", err)
	}
	if !bytes.Equal(k, wantK) {
		t.Fatalf("k %x, want %x", k, wantK)
	}
	if got, err := forwardEphPublic(ephSK); err != nil || !bytes.Equal(got, ephPub) {
		t.Fatalf("eph public %x, want %x (%v)", got, ephPub, err)
	}
}

func TestVectorForwardSeal(t *testing.T) {
	v := kdfVector(t)
	ephSK := vhex(t, v, "forward_eph_sk")
	hsM := vhex(t, v, "hs_M")
	deposit := vhex(t, v, "deposit")
	want := vhex(t, v, "sealed")

	sealed, err := SealForward(ephSK, hsM, deposit)
	if err != nil {
		t.Fatalf("SealForward: %v", err)
	}
	if !bytes.Equal(sealed, want) {
		t.Fatalf("sealed %x, want %x", sealed, want)
	}
}

func TestVectorProofOfWork(t *testing.T) {
	v := kdfVector(t)
	d, err := ParseDeposit(vhex(t, v, "deposit"))
	if err != nil {
		t.Fatal(err)
	}
	bits := uint32(v["pow_bits"].(float64))
	pow := uint64(v["pow"].(float64))
	want := vhex(t, v, "pow_hash")

	got := PowHash(d.Queue, d.Blob, pow)
	if !bytes.Equal(got[:], want) {
		t.Fatalf("pow hash %x, want %x", got, want)
	}
	if int(bits) > MaxPowBits {
		t.Fatalf("vector asks for %d bits", bits)
	}
	if !ValidPow(d.Queue, d.Blob, pow, bits) {
		t.Fatalf("the vector proof does not satisfy %d bits", bits)
	}
}

